#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
        assert(x>0 && y>0 && x+y<n);
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };

    // Place elements 1,2,...,n in order
    // After placing k elements, positions 0..k-1 are correct
    // We work on the subarray [k..n-1] conceptually but operations are on the whole array

    for(int k=0; k<n-2; k++){
        int val = k+1;
        int pos = -1;
        for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
        if(pos==k) continue; // already placed

        // We want to move p[pos] to position k
        // Strategy: use up to 2 operations

        // If pos is at n-1 (last position):
        //   apply(k+1, 1) if k+1+1<n => k+2<n => k<n-2 (guaranteed)
        //   This puts p[n-1] at position 0, then p[k+1..n-2] in middle, then p[0..k] at end
        //   Wait no: suffix=[p[n-1]], middle=[p[k+1]..p[n-2]], prefix=[p[0]..p[k]]
        //   Result: [p[n-1]] [p[k+1]..p[n-2]] [p[0]..p[k]]
        //   p[n-1]=val goes to position 0, but we want position k...

        // Better: first move element to position n-1, then use x=k+1, y=n-1-k-1+1... 
        // Let me think differently. 
        // To place val at position k: x=k, y=n-pos if that works? No...

        // Step 1: Move val to the last position if not there
        if(pos < n-1){
            // x=pos+1, y=n-1-pos: swaps [0..pos] with [pos+1..n-1]... no, x+y=n, need <n
            // x=pos-k, y=n-1-pos applied on conceptual subarray... but ops are global
            // Use: x=pos+1, y=n-1-pos if pos+1+n-1-pos=n not <n. So use y=n-2-pos if >0
            if(n-2-pos>0 && pos+1>0 && pos+1+n-2-pos<n){
                apply(pos+1, n-2-pos); // moves val to pos n-1-(n-2-pos)=pos+1... no
            }
            // Recalc
            for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
            if(pos<n-1 && pos>0){
                apply(pos, n-1-pos);
                for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
            } else if(pos==0 && n>2){
                apply(1, n-2);
                for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
                if(pos<n-1 && pos>0){
                    apply(pos, n-1-pos);
                    for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
                }
            }
        }
        if(pos==k) continue;
        if(pos==n-1 && k+2<=n-1){
            apply(k+1, 1);
            // val was at n-1, now at position 0... no: suffix=p[n-1], prefix=p[0..k]
            // result: [p[n-1], p[k+1..n-2], p[0..k]] -> val at pos 0
            // That puts val at 0 not k. Need different x,y.
            // x=1, y=n-1-k: [p[0]] [p[1..k]] [p[k+1..n-1]] but val at n-1 is in suffix
            // Hmm let me just try x=k, y=1 if k>0
        }
        // Reset and try cleaner approach
        for(int i=0;i<n;i++) if(p[i]==val){pos=i;break;}
        if(pos==k) continue;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
